mapper.select:
select t.machine_id machineId, t.machine_code machineCode, t.machine_name machineName, t.community_id communityId, t.type_id typeId, t.charge, t.sign, t.up_min upMin, t.check_sec checkSec, t.impl_bean implBean, t.create_time createTime, t.status_cd,t.status_cd statusCd, it.name typeName, ifa.factory_name factoryName, ip.param_id paramId, ip.machine_id machineId1, ip.community_id communityId1, ip.spec_cd specCd, ifs.spec_name specName, ip.value, ip.create_time createTime1, ip.status_cd statusCd1, ise.sensor_id sensorId, ise.machine_id machineId2, ise.sensor_type sensorType, ise.community_id communityId2, ise.min_value minValue, ise.max_value maxValue1, ise.units, ise.create_time createTime2, ise.status_cd statusCd2, td.name sensorTypeName from instrument t left join instrument_type it on t.type_id = it.type_id and it.status_cd = '0' left join instrument_factory ifa on t.impl_bean = ifa.factory_id and ifa.status_cd = '0' left join instrument_param ip on t.machine_id = ip.machine_id and t.community_id = ip.community_id and ip.status_cd = '0' left join instrument_factory_spec ifs on t.impl_bean = ifa.factory_id and ifa.factory_id = ifs.factory_id and ifs.spec_cd = ip.spec_cd and ifs.status_cd = '0' left join instrument_sensor ise on t.machine_id = ise.machine_id and ise.status_cd = '0' left join t_dict td on ise.sensor_type = td.status_cd and td.table_name = 'instrument_sensor' and td.table_columns = 'sensor_type' where 1 =1
and t.impl_bean= #{implBean}
and t.machine_id like concat('%', #{machineId}, '%')
and t.machine_code like concat('%', #{machineCode}, '%')
and t.charge= #{charge}
and t.up_min= #{upMin}
and t.check_sec= #{checkSec}
and t.sign= #{sign}
and t.type_id= #{typeId}
and t.status_cd= #{statusCd}
and t.community_id= #{communityId}
and t.machine_name like concat('%', #{machineName}, '%')
order by t.create_time desc
limit #{page}, #{row}

